func lisLength(a: Array<Int64>): Int64 {
 if (a.isEmpty()) { return 0 }
 let dp=Array<Int64>(a.size,repeat:1)
 var best: Int64=1
 for (i in 0..a.size) {
  for (j in 0..i) { if (a[j]<=a[i]) {dp[i]=max(dp[i],dp[j]+1)} }
  best=dp[i]
 }
 best
}

