func shortestPaths(w: Array<Array<Int64>>, start: Int64): Array<Int64> {
 let n=w.size
 let d=Array<Int64>(n,repeat:100000)
 d[start]=0
 for (_ in 0..n-1) {for (i in 0..n) {for (j in 0..n) {
  if (w[i][j]>0 && d[i]<100000) {d[j]=min(d[j],d[i]+w[i][j])}
 }}}
 for (i in 0..n) {if(d[i]==100000){d[i] = 0}}
 d
}

