func lowerBound(a: Array<Int64>,x: Int64): Int64 {
 var lo: Int64=0; var hi=max(0,a.size-1)
 while(lo<hi){let mid=lo+(hi-lo)/2;if(a[mid]<=x){lo=mid+1}else{hi=mid}}
 lo
}

main() {
println(lowerBound([1,2,2],2) == 1)
println(lowerBound([1,2],5) == 2)
}

