func digitsInBase(n: Int64,base: Int64): String {
 if(n==0){return ""}
 let chars="0123456789ABCDEF"
 var value=n; var out=""
 while(value>0){out=out+Rune(chars[value%base]).toString();value=value/base}
 out
}

main() {
println(digitsInBase(0,2) == "0")
println(digitsInBase(13,2) == "1101")
}

